var sourceName = 'spacetrack-ss';
var cooldownMinutes = 60;
var key = 'circuitBreaker_' + sourceName;
var state = flow.get(key) || { open: false, failCount: 0, openedAt: 0 };
if (state.open) {
    var elapsedMin = (Date.now() - state.openedAt) / 60000;
    if (elapsedMin < cooldownMinutes) {
        node.status({ fill: 'red', shape: 'ring', text: sourceName + ': OPEN (' + Math.round(cooldownMinutes - elapsedMin) + 'm left)' });
        return null;
    }
    node.status({ fill: 'yellow', shape: 'dot', text: sourceName + ': testing recovery' });
}
msg._circuitBreakerSource = sourceName;
return msg;

var NORAD_IDS = [25544, 36086, 48274, 49044, 53239, 54216];
// Added 2026-08-30 after checking against Celestrak's live 'stations' group:
// 36086 = POISK, 49044 = NAUKA -- both separate-catalog Russian ISS modules
// that were missing from the original 4-object list.

if (!NORAD_IDS.length) {
    node.status({ fill: 'red', shape: 'ring', text: 'NORAD_IDS list is empty -- see tab info' });
    return null;
}

var cookie = flow.get('spacetrack_session_cookie');
if (!cookie) {
    node.status({ fill: 'red', shape: 'ring', text: 'no session cookie -- login step failed upstream' });
    return null;
}

var queryUrl = 'https://www.space-track.org/basicspacedata/query/class/gp/NORAD_CAT_ID/' +
    NORAD_IDS.join(',') + '/orderby/NORAD_CAT_ID/format/json';

msg.url = queryUrl;
msg.method = 'GET';
msg.headers = { Cookie: cookie };
return msg;

var ERROR_CODES = [301, 400, 401, 403, 404, 429, 500, 502, 503, 504];
var TRIP_THRESHOLD = 1;
var sourceName = msg._circuitBreakerSource || node.id;
var key = 'circuitBreaker_' + sourceName;
var state = flow.get(key) || { open: false, failCount: 0, openedAt: 0 };
var code = msg.statusCode;
var bodyLooksLikeError = typeof msg.payload === 'string' && /error|invalid|denied/i.test(msg.payload.slice(0, 300));
var isError = ERROR_CODES.indexOf(code) !== -1 || bodyLooksLikeError;
if (isError) {
    state.failCount = (state.failCount || 0) + 1;
    if (state.failCount >= TRIP_THRESHOLD) {
        state.open = true; state.openedAt = Date.now();
        state.lastError = { code: code, at: new Date().toISOString() };
        flow.set(key, state);
        node.error('CIRCUIT BREAKER TRIPPED: ' + sourceName + ' returned HTTP ' + code, msg);
        node.status({ fill: 'red', shape: 'dot', text: sourceName + ': TRIPPED (HTTP ' + code + ')' });
        return [null, { payload: { sourceName: sourceName, statusCode: code, failCount: state.failCount, timestamp: new Date().toISOString() } }];
    }
    flow.set(key, state);
    node.warn(sourceName + ': error ' + code);
    return [null, null];
}
if (state.failCount > 0 || state.open) { node.status({ fill: 'green', shape: 'dot', text: sourceName + ': recovered' }); }
flow.set(key, { open: false, failCount: 0, openedAt: 0 });
return [msg, null];

var arr = Array.isArray(msg.payload) ? msg.payload : [];
var sats = [];
arr.forEach(function (o) {
    if (o && o.TLE_LINE1 && o.TLE_LINE2) {
        sats.push({ name: o.OBJECT_NAME || ('NORAD ' + o.NORAD_CAT_ID), line1: o.TLE_LINE1, line2: o.TLE_LINE2, noradId: String(o.NORAD_CAT_ID), country: o.COUNTRY_CODE || 'UNKNOWN' });
    }
});
flow.set('ss_sats', sats);
node.status({ fill: 'blue', shape: 'dot', text: sats.length + ' objects cached' });
return null;

var channelName = 'SystemAlerts'; var markerLat = 36.1627; var markerLon = -86.7816; var staleMinutes = 60;
function esc(s) { return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
var a = msg.payload;
var now = new Date(); var start = now.toISOString();
var stale = new Date(now.getTime() + staleMinutes * 60000).toISOString();
var uid = 'circuit-alert-' + a.sourceName;
var remarks = 'CIRCUIT BREAKER TRIPPED | Source: ' + a.sourceName + ' | HTTP ' + a.statusCode + ' | Failures: ' + a.failCount;
var cot = '<?xml version="1.0" encoding="UTF-8"?>' + '<event version="2.0" uid="' + esc(uid) + '" type="b-m-p-s-m" how="m-g" time="' + start + '" start="' + start + '" stale="' + stale + '">' + '<point lat="' + markerLat + '" lon="' + markerLon + '" hae="0" ce="9999999.0" le="9999999.0"/>' + '<detail><contact callsign="ALERT: ' + esc(a.sourceName) + '"/><color value="-65536"/>' + '<remarks>' + esc(remarks) + '</remarks></detail></event>';
msg.payload = cot;
return msg;

var user = env.get('SPACETRACK_USER');
var pass = env.get('SPACETRACK_PASS');
if (!user || !pass) {
    node.status({ fill: 'red', shape: 'ring', text: 'Set SPACETRACK_USER/PASS in tab env vars' });
    return null;
}
msg.payload = 'identity=' + encodeURIComponent(user) + '&password=' + encodeURIComponent(pass);
msg.headers = { 'Content-Type': 'application/x-www-form-urlencoded' };
return msg;

var setCookie = msg.headers && msg.headers['set-cookie'];
if (!setCookie || !setCookie.length) {
    node.status({ fill: 'red', shape: 'ring', text: 'login failed -- no Set-Cookie received' });
    node.error('Space-Track login: no Set-Cookie header in response', msg);
    return null;
}
var cookieHeader = setCookie.map(function (c) { return c.split(';')[0]; }).join('; ');
flow.set('spacetrack_session_cookie', cookieHeader);
node.status({ fill: 'green', shape: 'dot', text: 'session cookie captured' });
return msg;

var staleSeconds = 120;
var FRIENDLY = ['US','UK','FR','GERMANY','GER','IT','CANADA','CA','SPAIN','NETH','NETHERLANDS','BEL','NORWAY','DEN','POLAND','TURK','PORTUGAL','GREECE','CZCH','ROMANIA','HUNGARY','SVK','HRV','JPN','JAPAN','AUS','AUSTRALIA','ROK','SKOR','SKOREA','NZ','ESA','EUME','ISRA','MEX','RP','JOR','THAI','SAUD','SWTZ','IND','ARGN','INDO','MALA','BRAZ','SAFR','ISS','AB'];
var HOSTILE = ['CIS','RUSSIA','SU','PRC','CHN','CHINA','PRK','NKOR','NORTH KOREA','CUBA','VTNM','VIETNAM','LAOS'];

var FORCE_FRIENDLY_IDS = ['25544', '36086', '49044']; // ISS ZARYA, POISK, NAUKA

var OFFSET_DEG = 0.015;
var POSITION_OFFSETS = {
    '36086': { dLat:  OFFSET_DEG, dLon:  OFFSET_DEG },
    '49044': { dLat: -OFFSET_DEG, dLon: -OFFSET_DEG },
    '53239': { dLat:  OFFSET_DEG, dLon:  OFFSET_DEG },
    '54216': { dLat: -OFFSET_DEG, dLon: -OFFSET_DEG }
};

var sats = flow.get('ss_sats') || [];
if (!sats.length) { node.status({ fill: 'grey', shape: 'ring', text: 'waiting for first Space-Track refresh' }); return null; }
var now = new Date();
var startIso = now.toISOString();
var staleIso = new Date(now.getTime() + staleSeconds * 1000).toISOString();
var gmst = satellite.gstime(now);
var msgs = []; var errors = 0; var staleTle = 0;
// Skip satellites whose element set is older than this: they are dead / re-entered
// (Space-Track stops updating them) and propagate to wrong positions or fail.
var MAX_TLE_AGE_DAYS = 30;
sats.forEach(function (s) {
    try {
        var satrec = satellite.twoline2satrec(s.line1, s.line2);
        var epochMs = (satrec.jdsatepoch + (satrec.jdsatepochF || 0) - 2440587.5) * 86400000;
        if (!isFinite(epochMs) || (now.getTime() - epochMs) > MAX_TLE_AGE_DAYS * 86400000) { staleTle++; return; }
        var pv = satellite.propagate(satrec, now);
        if (!pv || !pv.position) { errors++; return; }
        var geo = satellite.eciToGeodetic(pv.position, gmst);
        var lat = satellite.degreesLat(geo.latitude);
        var lon = satellite.degreesLong(geo.longitude);
        var altKm = geo.height;

        var offset = POSITION_OFFSETS[s.noradId];
        var isOffset = !!offset;
        if (offset) { lat += offset.dLat; lon += offset.dLon; }
        var cc = (s.country || 'UNKNOWN').toUpperCase();
        var aff = 'u';
        if (FORCE_FRIENDLY_IDS.indexOf(s.noradId) !== -1) { aff = 'f'; }
        else if (FRIENDLY.indexOf(cc) !== -1) { aff = 'f'; } else if (HOSTILE.indexOf(cc) !== -1) { aff = 'h'; }
        var funcLetter = 'T'; var cotExt = '';
        var affLetter = (aff === 'f') ? 'F' : (aff === 'h') ? 'H' : 'U';
        var cotType = 'a-' + aff + '-P-' + funcLetter + cotExt;
        var sidc = 'S' + affLetter + 'P*' + funcLetter + '-----*****';
        var uid = 'sat-' + s.noradId;
        var radio = (flow.get('ss_radio') || {})[s.noradId];
        var remarks = 'NORAD ' + s.noradId + ' | Owner: ' + cc + ' | Alt: ' + altKm.toFixed(1) + ' km | Name: ' + s.name +
            (radio ? ' | Radio: ' + radio : '') +
            (isOffset ? ' | NOTE: position offset ~1.5km for map legibility -- module is physically docked/co-located with its station, not independently tracked' : '');
        var cot = '<?xml version="1.0" encoding="UTF-8"?>' + '<event version="2.0" uid="' + uid + '" type="' + cotType + '" how="m-g" time="' + startIso + '" start="' + startIso + '" stale="' + staleIso + '">' + '<point lat="' + lat.toFixed(6) + '" lon="' + lon.toFixed(6) + '" hae="' + (altKm * 1000).toFixed(0) + '" ce="9999999.0" le="9999999.0"/>' + '<detail>' + '<contact callsign="' + s.name.replace(/&/g,'&amp;').replace(/</g,'&lt;') + '"/>' + '<remarks>' + remarks.replace(/&/g,'&amp;').replace(/</g,'&lt;') + '</remarks>' + '<milsym id="' + sidc + '"/>' + '<milicon id="' + sidc + '"/>' + '</detail>' + '</event>';
        msgs.push({ payload: cot });
    } catch (e) { errors++; }
});
node.status({ fill: 'green', shape: 'dot', text: msgs.length + ' sats emitted' + (staleTle ? (', ' + staleTle + ' skipped (TLE > ' + MAX_TLE_AGE_DAYS + 'd old)') : '') + (errors ? (', ' + errors + ' errors') : '') });
return [msgs];

var sourceName = msg.topic;
if (!sourceName) { node.warn('Set the inject node topic to the sourceName to reset'); return null; }
flow.set('circuitBreaker_' + sourceName, { open: false, failCount: 0, openedAt: 0 });
node.warn('Circuit breaker manually cleared for: ' + sourceName);
node.status({ fill: 'green', shape: 'dot', text: sourceName + ': manually cleared' });
return null;

var sats = flow.get('ss_sats') || [];
msg.payload = JSON.stringify({
    count: sats.length,
    objects: sats.map(function (s) {
        return { name: s.name, noradId: s.noradId, country: s.country };
    })
}, null, 2);
msg.headers = { 'Content-Type': 'application/json' };
return msg;

var NORAD_IDS = [25544, 36086, 48274, 49044, 53239, 54216]; // same 6 objects as the Space-Track query
var msgs = NORAD_IDS.map(function (id) {
    return {
        url: 'https://db.satnogs.org/api/transmitters/?satellite__norad_cat_id=' + id + '&status=active&format=json',
        method: 'GET',
        noradId: String(id)
    };
});
node.status({ fill: 'blue', shape: 'dot', text: 'querying SatNOGS for ' + msgs.length + ' objects' });
return [msgs];

var existing = flow.get('ss_radio') || {};
var arr = Array.isArray(msg.payload) ? msg.payload : [];
if (arr.length) {
    var t = arr[0];
    var downlink = t.downlink_low ? (t.downlink_low / 1e6).toFixed(3) + ' MHz' : null;
    var uplink = t.uplink_low ? (t.uplink_low / 1e6).toFixed(3) + ' MHz' : null;
    var mode = t.mode || '';
    var parts = [];
    if (downlink) parts.push('RX/Downlink ' + downlink + (mode ? ' ' + mode : ''));
    if (uplink) parts.push('TX/Uplink ' + uplink + (mode ? ' ' + mode : ''));
    existing[msg.noradId] = parts.length ? parts.join(' | ') : null;
} else {
    existing[msg.noradId] = null;
}
flow.set('ss_radio', existing);
node.status({ fill: 'blue', shape: 'dot', text: Object.keys(existing).length + ' radio entries cached' });
return null;
